class Probe extends AsyncDirective {
  part: any;
  label = "";
  render(label: string) { return noChange; }
  update(part: any, [label]: [string]) {
    this.part = part;
    this.label = label;
    this.record("update");
    return noChange;
  }
  disconnected() { this.record("disconnected"); }
  reconnected() { this.record("reconnected"); }
  record(kind: string) {
    logs.push({ kind, label: this.label, directiveConnected: this.isConnected,
      optionInitialConnected: this.part?.options?.isConnected,
      hostConnected: this.part?.options?.host?.isConnected,
      targetConnected: this.part?.element?.isConnected });
