class Other extends AsyncDirective {
  render() { return noChange; }
  disconnected() { logs.push({kind:"other-disconnected", directiveConnected:this.isConnected}); }
  reconnected() { logs.push({kind:"other-reconnected", directiveConnected:this.isConnected}); }
}
const other = directive(Other);
class Host extends LitElement {
  mode = "probe";
  cacheOn = true;
  render() {
    if (this.mode === "cache") return html`${cache(this.cacheOn ? html`<div ${probe("cache")}></div>` : html`<span>cached away</span>`)}`;
