let host = await fresh();
host.mode = "none"; host.requestUpdate(); await host.updateComplete; host.remove();
mark("temporary host disconnect and reconnect");
host = await fresh(); host.remove(); document.body.append(host); await host.updateComplete; host.remove();
mark("replacement while already disconnected");
host = await fresh(); host.remove(); host.mode = "other"; host.requestUpdate(); await host.updateComplete; document.body.append(host); await host.updateComplete; host.remove();
mark("cache temporarily disconnects while host stays connected");
host = await fresh(); host.mode = "cache"; host.requestUpdate(); await host.updateComplete;
host.cacheOn = false; host.requestUpdate(); await host.updateComplete;
host.cacheOn = true; host.requestUpdate(); await host.updateComplete; host.remove();

const cases={};let current;for(const entry of logs){if(entry.case){current=entry.case;cases[current]=[];}else cases[current].push(entry);}
const results=[];const check=(name,actual,expected)=>results.push({name,actual,expected,ok:JSON.stringify(actual)===JSON.stringify(expected)});
const direct=cases["direct removal while connected"].find(row=>row.kind==="disconnected");
const cached=cases["cache temporarily disconnects while host stays connected"].find(row=>row.kind==="disconnected"&&row.label==="cache");
const view=row=>({directive:row.directiveConnected,host:row.hostConnected,target:row.targetConnected});
check("removal public state",view(direct),{directive:false,host:true,target:true});
check("temporary cache has identical public state",view(cached),view(direct));
const replacement=cases["replacement while already disconnected"];
