  inputs=createOrderedStyleInputs({padding:(value)=>{if(typeof value!=="number")throw Error("numeric fixture");return value;}});
}
customElements.define("explicit-clear-target",StyleTarget);
class ExplicitInputs extends AsyncDirective {
  previousKeys=[];
  render(values){return noChange;}
