}
const explicitInputs=directive(ExplicitInputs);
const container=document.createElement("div");document.body.append(container);
const draw=(values)=>render(html`<explicit-clear-target ${explicitInputs(values)}></explicit-clear-target>`,container);
const root=draw({padding:16});const target=container.firstElementChild;
check("explicit helper applies supplied input",target.inputs.get("padding"),16);
root.setConnected(false);
