draw({});
check("empty helper clears while disconnected",target.inputs.get("padding")===undefined,true);
root.setConnected(true);
check("reconnect does not restore cleared input",target.inputs.get("padding")===undefined,true);
draw({padding:20});draw({});
check("empty helper clears while connected",target.inputs.get("padding")===undefined,true);
container.remove();
window.__results={results,logs};

